import math
    import random
    import time

    LANGUAGE_WRAPPER = 'Consider a {outer_w} by {outer_h} axis-aligned rectangle. A smaller rectangle is inscribed with exactly one vertex on each side of the larger rectangle and is called unstuck if it can be rotated, however slightly, about its center while remaining entirely within the larger rectangle. Among all such unstuck inscribed rectangles, the smallest perimeter has the form sqrt(N) for a positive integer N. Find N.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# Generate a non-square rectangle with reasonably sized integer dimensions.
# Ensure outer_w > outer_h to fix orientation and avoid trivial square symmetry.
for _ in range(1000):
    a = rng.randint(6, 80)
    b = rng.randint(6, 80)
    if a != b:
        w = max(a, b)
        h = min(a, b)
        # Optional extra filter to avoid too-close sizes which make the boundary case delicate
        if w - h >= 2:
            return {'outer_w': w, 'outer_h': h}
# Fallback in case random attempts didn't succeed for some reason
return {'outer_w': 8, 'outer_h': 6}

    def verifier(assign):
# Validate domain constraints and compute the correct N.
# The minimal perimeter among unstuck inscribed rectangles in a W by H rectangle (W>H)
# is 2 * sqrt(W * (W + H)), so N = 4 * W * (W + H).
try:
    W = assign['outer_w']
    H = assign['outer_h']
except Exception:
    # Missing keys
    return (False, None)
# Type and value checks
if not (isinstance(W, int) and isinstance(H, int)):
    # Must be integers
    return (False, None)
if W <= 0 or H <= 0:
    # Positive dimensions required
    return (False, None)
if W == H:
    # Exclude squares to enforce the harder asymmetric case
    return (False, None)
if W < H:
    # Enforce W>H to keep orientation consistent
    return (False, None)
# Compute answer: N is guaranteed integer
N = 4 * W * (W + H)
return (True, N)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

